FIELDS='candidate_id title network_form operating_base proposed_paths passenger_and_purpose season_and_stay current_alternative rw_product growth_sources competitor_and_response frequency_proposal resource_requirement stop_rule ancestor_ids'.split()
def main():
    records=[]
    for line in SEEDS.splitlines():
        vals=line.split('|');assert len(vals)==len(FIELDS),(vals[0],len(vals))
        r=dict(zip(FIELDS,vals));deep=DEEP.get(r['candidate_id'])
        r.update(candidate_version='1',author='GPT-6 Astra hypotheses role; concrete research specification, not claim of original family',family_provenance='existing_hypotheses.csv; contributions/existing_map/report.md',selected_for_deepening=bool(deep),selection_rationale=deep[1] if deep else 'Сохранён в широком поиске; отсутствие в первой очереди не означает опровержения или низкого спроса',experiment_id=deep[0] if deep else '',specific_test=deep[2] if deep else r['stop_rule'],data_request_ids=deep[3] if deep else 'D01;D05;D08;D09;D11;D12;D27;D30',demand_value=None,demand_unit='one-way endpoint journeys/month/direction/purpose',demand_status='UNKNOWN',demand_missing_reason='Нет сопоставимого наблюдённого или калиброванного OD этой программы',net_fare_rub=None,net_fare_status='UNKNOWN',net_fare_definition='Получаемая RW выручка за всю поездку после согласованных налогов/сборов/возвратов/комиссий; допуслуги отдельно; без дублирования сегментов',frequency_status='SCENARIO',available_aircraft=None,resource_status='UNKNOWN',evaluation_status='NOT_EVALUATED',specification_status='RESEARCH_CANDIDATE',value_type='SCENARIO',acquisition_status='NOT_APPLICABLE_AUTHORED',primary_evidence_ids='',reward='Прирост оплаченных поездок и net contribution после baseline при выполнении stop_rule; величина UNKNOWN',risk='Неизвестный OD/получаемый тариф/ресурс; конкретный риск указан в stop_rule и resource_requirement',political_change_date=None)
        records.append(r)
    evidence={'C11':'SAO10;SAO11','C14':'SAO01;SAO02;SAO07;SAO08','C10':'SAO03;SAO04','C21':'HYP-S02;SAO05','C22':'SAO09','C34':'SAO06'}
    aliases={'T16_RADIAL_UFA':'T16_RADIAL','FRONT_SCREEN':'FRONT_GAP'}
    for r in records:
        r['primary_evidence_ids']=evidence.get(r['candidate_id'],'')
        r['ancestor_ids']=';'.join(aliases.get(i,i) for i in r['ancestor_ids'].split(';'))
        r['program_manifest']=None
    (ROOT/'inputs/candidate_catalog.json').write_text(json.dumps({'schema_version':'candidate-research-v1','baseline':'C00 current program; no incremental launch = zero project delta, not zero company profit','candidates':records},ensure_ascii=False,indent=2)+'\n')
    with (ROOT/'candidates.csv').open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(records[0]));w.writeheader();w.writerows(records)
    print(json.dumps({'candidates':len(records),'deepening':[r['candidate_id'] for r in records if r['selected_for_deepening']]}))

if __name__=='__main__':main()
